create table if not exists streaming_series(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),title text not null,slug text not null,description text,cover_url text,status text not null default 'draft' check(status in('draft','published','archived')),premium boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,slug));
create table if not exists streaming_seasons(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),series_id uuid not null references streaming_series(id) on delete cascade,title text not null,season_number integer not null check(season_number>0),description text,status text not null default 'draft' check(status in('draft','published','archived')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(series_id,season_number));
create table if not exists streaming_episodes(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),season_id uuid not null references streaming_seasons(id) on delete cascade,title text not null,slug text not null,episode_number integer not null check(episode_number>0),description text,thumbnail_url text,duration_seconds integer check(duration_seconds is null or duration_seconds>=0),status text not null default 'draft' check(status in('draft','published','archived')),premium boolean not null default true,provider text,provider_asset_id text,provider_playback_id text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(season_id,episode_number),unique(organization_id,slug));
create table if not exists streaming_entitlements(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),subscriber_id uuid not null references subscribers(id),subscription_id uuid references subscriptions(id),scope_type text not null default 'catalog' check(scope_type in('catalog','series','episode')),series_id uuid references streaming_series(id),episode_id uuid references streaming_episodes(id),starts_at timestamptz not null default now(),ends_at timestamptz,active boolean not null default true,created_at timestamptz not null default now(),check((scope_type='catalog' and series_id is null and episode_id is null) or (scope_type='series' and series_id is not null and episode_id is null) or (scope_type='episode' and episode_id is not null)));
create table if not exists streaming_watch_history(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),subscriber_id uuid not null references subscribers(id),episode_id uuid not null references streaming_episodes(id),progress_seconds integer not null default 0 check(progress_seconds>=0),completed boolean not null default false,last_watched_at timestamptz not null default now(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(subscriber_id,episode_id));
create table if not exists streaming_favorites(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),subscriber_id uuid not null references subscribers(id),series_id uuid not null references streaming_series(id),created_at timestamptz not null default now(),unique(subscriber_id,series_id));
create table if not exists streaming_events(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),subscriber_id uuid references subscribers(id),episode_id uuid references streaming_episodes(id),event_type text not null check(event_type in('play','pause','progress','complete')),position_seconds integer check(position_seconds is null or position_seconds>=0),created_at timestamptz not null default now());
create index if not exists idx_streaming_series_org_status on streaming_series(organization_id,status);create index if not exists idx_streaming_seasons_series on streaming_seasons(series_id,season_number);create index if not exists idx_streaming_episodes_season on streaming_episodes(season_id,episode_number);create index if not exists idx_streaming_entitlements_subscriber on streaming_entitlements(subscriber_id,active);create index if not exists idx_streaming_history_subscriber on streaming_watch_history(subscriber_id,last_watched_at desc);create index if not exists idx_streaming_events_org_created on streaming_events(organization_id,created_at desc);
alter table streaming_series enable row level security;alter table streaming_seasons enable row level security;alter table streaming_episodes enable row level security;alter table streaming_entitlements enable row level security;alter table streaming_watch_history enable row level security;alter table streaming_favorites enable row level security;alter table streaming_events enable row level security;